const emails = $input.all();
if (!emails || emails.length === 0) {
  return [{ json: { total: 0, emails: [] } }];
}

// Function to extract only the new email content (remove quoted reply)
function extractNewContent(bodyText) {
  if (!bodyText) return bodyText;

  // Find where the quoted reply begins
  const lines = bodyText.split(/\r?\n/);
  let newContentLines = [];
  let foundQuotedReply = false;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const lowerLine = line.toLowerCase();

    // Check for common reply markers
    const isReplyMarker = 
      lowerLine.match(/^on .+? wrote:/i) ||
      lowerLine.match(/^-------- original message --------/i) ||
      lowerLine.match(/^-----original message-----/i) ||
      (lowerLine.trim() === '>') ||
      (line.trim().startsWith('>') && i > 0 && lines[i-1].trim() === '') ||
      lowerLine.includes('wrote:') && lowerLine.includes('@');

    if (isReplyMarker && !foundQuotedReply) {
      foundQuotedReply = true;
      break;
    }

    if (!foundQuotedReply) {
      newContentLines.push(line);
    }
  }

  let newContent = newContentLines.join('\n').trim();

  // Also remove any lines that start with '>' (quoted text)
  const withoutQuotedLines = newContent.split(/\r?\n/).filter(line => !line.trim().startsWith('>')).join('\n');

  return withoutQuotedLines || newContent;
}

const structured = emails.map(e => {
  const raw = Object.fromEntries(
    Object.entries(e.json).map(([k, v]) => [k.toLowerCase(), v])
  );

  let senderName = null;
  let senderEmail = '';
  if (typeof raw.from === 'string') {
    const match = raw.from.match(/^(.+?)\s*<(.+?)>$/);
    senderName  = match ? match[1].trim().replace(/^"|"$/g, '') : null;
    senderEmail = match ? match[2].trim() : raw.from.trim();
  } else if (raw.from?.value?.[0]) {
    senderName  = raw.from.value[0].name  || null;
    senderEmail = raw.from.value[0].address || '';
  } else if (typeof raw.from?.text === 'string') {
    const match = raw.from.text.match(/^(.+?)\s*<(.+?)>$/);
    senderName  = match ? match[1].trim().replace(/^"|"$/g, '') : null;
    senderEmail = match ? match[2].trim() : raw.from.text.trim();
  }

  const date = raw.internaldate
    ? new Date(parseInt(raw.internaldate)).toISOString()
    : raw.date || null;

  const fullBody = raw.text || raw.html || raw.snippet || null;
  const cleanBody = extractNewContent(fullBody);

  return {
    gmail_id:    raw.id,
    threadId:    raw.threadid || null,
    senderName,
    senderEmail,
    subject:     raw.subject || 'No Subject',
    date,
    body:        cleanBody  // ← Now only contains NEW content, no quoted reply
  };
}).filter(e => {
  if (!e.body) return true;
  const normalized = e.body.trim().replace(/\s+/g, ' ').toLowerCase();
  return !normalized.includes("sent with care · confidential");
});

return [{
  json: {
    total:  structured.length,
    emails: structured
  }
}];
